data.value:
SELECT TOP 20 AUTO_NUMBER, DATE, TIME, LAST_NAME, FIRST_NAME, EMAIL, COMPANY
FROM CONTACT
ORDER BY AUTO_NUMBER DESC;

SELECT TOP 20 AUTO_NUMBER, DATE, EMAIL
FROM SUBSCRIBE
ORDER BY AUTO_NUMBER DESC;

SELECT TOP 50 AUTO_NUMBER, DATE, TIME, IP_ADDRESS, USER_NAME, ACTION
FROM LOGIN
ORDER BY AUTO_NUMBER DESC;

SELECT USER_NAME, FIRST_NAME, LAST_NAME, TotpEnabled
FROM USERS
ORDER BY USER_NAME;

-- Un utilisateur a perdu son téléphone ET ses codes de secours : remplacer nom par son nom d’utilisateur.
-- (Un autre administrateur peut aussi le faire depuis la page « Utilisateurs ».)
UPDATE USERS SET TotpSecret = NULL, TotpEnabled = 0, TotpLastStep = NULL, TotpRecovery = NULL WHERE USER_NAME = 'nom';
